import json,sys
d=json.load(open('/tmp/vo.json'))
def walk(n,out):
    if isinstance(n,dict):
        if n.get('type')=='text': out.append(n.get('text',''))
        elif n.get('type')=='reference': out.append('['+str(n.get('title') or n.get('identifier',''))+']')
        elif n.get('type')=='heading': out.append('\n## '+n.get('text','')+'\n')
        for k,v in n.items():
            if k in ('text',): continue
            walk(v,out)
    elif isinstance(n,list):
        for i in n: walk(i,out)
out=[]
walk(d.get('primaryContentSections'),out)
print(' '.join(out))
